/** Single source of truth for where a video's files live in storage. */
export const videoStorageKeys = {
  root: (videoId) => `videos/${videoId}`,
  source: (videoId, extension) => `videos/${videoId}/source.${extension}`,
  // Everything below is generated by processing and can be deleted and rebuilt.
  thumbnail: (videoId) => `videos/${videoId}/thumbnail.jpg`,
  renditions: (videoId) => `videos/${videoId}/renditions`,
  rendition: (videoId, label) => `videos/${videoId}/renditions/${label}.mp4`,
};
